import {
  Box,
  Button,
  Container,
  Grid,
  InputAdornment,
  TextField,
  Tooltip,
  Typography,
} from "@mui/material";
import React, { useEffect, useState } from "react";
import HelpDocumentCards from "./HelpDocumentCards";
import streamLineUserImg from "../../../../assets/images/streamlineUser.png";
import enhanceADManagerImg from "../../../../assets/images/enhanceADManager.png";
import adManagerFeaturesImg from "../../../../assets/images/adManagerFeatures.png";
import automateEmployeeImg from "../../../../assets/images/automateEmployee.png";
import optimizeOfficeImg from "../../../../assets/images/optimizeOffice.png";
import SearchIcon from "@mui/icons-material/Search";
import "../../../../styles/animation.css";
import { useParams } from "react-router-dom";
import { toastError } from "src/utils/utils";

import { ApiEndpoints } from "src/network/endpoints";
import { axiosInstance } from "src/network/adapter";
import FallbackSpinner from "src/@core/components/spinner";

const HelpDocuments = () => {
  const helpDocuments = [
    {
      title:
        "Streamline user life cycle management with ADManager Plus orchestration",
      img: streamLineUserImg,
    },
    {
      title:
        "Enhance ADManager Plus security using the Product Security Hardening feature",
      img: enhanceADManagerImg,
    },
    {
      title:
        "3 features of ADManager Plus to improve AD management during remote work",
      img: adManagerFeaturesImg,
    },
    {
      title:
        "Automate employee life cycle management with the ADManager Plus-Ultipro integration",
      img: automateEmployeeImg,
    },
    {
      title: "Optimize Office 365 license management with ADManager Plus",
      img: optimizeOfficeImg,
    },
  ];

  const resourcesOptions = [
    "Help Documents",
    "Brochures",
    "Guides",
    "E-books & whitepapers",
    "Case studies",
    "Videos",
    "Blogs",
    "Newsletter",
  ];

  const [visibleCards, setVisibleCards] = useState([]);
  const [visibleButtons, setVisibleButtons] = useState([]);
  const [resourcesData, setResourcesData] = useState([]);
  const [resourcesDetails, setResourcesDetails] = useState([]);
  const [resourceTitle, setResourceTitle] = useState("");
  const [loading, setLoading] = useState(false);
  const { id } = useParams();
  const itSolutionId = id.split("-").pop();
  const [searchQuery, setSearchQuery] = useState("");
  const [activeButtonId, setActiveButtonId] = useState(null);

  useEffect(() => {
    helpDocuments.forEach((_, index) => {
      setTimeout(() => {
        setVisibleCards((prev) => [...prev, index]);
      }, index * 300); // Stagger each card by 300ms
    });

    resourcesOptions.forEach((_, index) => {
      setTimeout(() => {
        setVisibleButtons((prev) => [...prev, index]);
      }, index * 200); // Stagger each button by 200ms
    });
  }, []);

  const fetchResourcesData = () => {
    setLoading(true);
    axiosInstance
      .get(ApiEndpoints.IT_SOLUTION_RESOURCES.list(itSolutionId))
      .then((response) => {
        const responseData = response.data.data;
        setResourcesData(response.data.data);
        if (responseData.length > 0) {
          fetchResourcesDetailedData(responseData[0].id);
          setActiveButtonId(responseData[0].id);
          setResourceTitle(responseData[0].title); // Assuming 'id' is the identifier for each resource
        }
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };

  const handleBtnClick = (resourcesId, resourceTitle) => {
    fetchResourcesDetailedData(resourcesId);
    setResourceTitle(resourceTitle);
    setActiveButtonId(resourcesId);
  };
  const fetchResourcesDetailedData = (resourcesId) => {
    setLoading(true);
    axiosInstance
      .get(ApiEndpoints.IT_SOLUTION_RESOURCES_DETAILS.list(resourcesId))
      .then((response) => {
        setResourcesDetails(response.data.data);
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };

  const filteredResourcesDetails = resourcesDetails.filter((item) =>
    item.title.toLowerCase().includes(searchQuery.toLowerCase())
  );

  useEffect(() => {
    fetchResourcesData();
  }, [id]);

  if (loading) return <FallbackSpinner />;
  return (
    <>
      <Box>
        <Container
          maxWidth={"xl"}
          sx={{ px: { xs: 5, sm: 10, lg: 15, xl: 20 }, pb: 5 }}
        >
          <Grid container rowGap={{ xs: 6, sm: 20 }}>
            <Grid
              item
              xs={12}
              sx={{
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                gap: { xs: 2, md: 0 },
              }}
            >
              <Typography
                sx={{
                  fontSize: { xs: "26px", sm: "30px", md: "40px", lg: "48px" },
                  lineHeight: {
                    xs: "34px",
                    sm: "44px",
                    md: "54px",
                    lg: "73px",
                  },
                  fontWeight: 500,
                  color: "#201D28",
                  textTransform: "capitalize",
                  wordBreak: "break-word",
                  whiteSpace: "normal",
                  textAlign: "center",
                }}
                className="fade-in-up-whoweare"
              >
                {resourceTitle}
              </Typography>
            </Grid>
            <Grid item container columnSpacing={10} rowGap={{ xs: 6, md: 0 }}>
              <Grid
                item
                md={3}
                sx={{
                  display: "flex",
                  flexDirection: "column",
                  gap: 5,
                  flexGrow: 1,
                }}
              >
                <Box>
                  <TextField
                    fullWidth
                    placeholder="Search"
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    InputProps={{
                      endAdornment: (
                        <InputAdornment position="end">
                          <Box
                            sx={{
                              display: "flex",
                              alignItems: "center",
                              borderLeft: "1px solid #ccc",
                              paddingLeft: "8px",
                              marginRight: "10px",
                            }}
                          >
                            <SearchIcon />
                          </Box>
                        </InputAdornment>
                      ),
                      sx: {
                        border: "1.5px solid #C8C8C8",
                        borderRadius: "14px",
                        "&::placeholder": {
                          display: "flex",
                          alignItems: "center",
                        },
                      },
                    }}
                    sx={{
                      "& input::placeholder": {
                        color: "#989898",
                        fontSize: "16px",
                        opacity: 1,
                        display: "flex",
                        alignItems: "center",
                      },
                      "& .MuiInputAdornment-root": {
                        marginRight: 0, // Remove default right margin of the adornment
                      },
                    }}
                  />
                </Box>
                <Box
                  sx={{
                    display: "flex",
                    flexDirection: "column",
                    gap: 2,
                  }}
                >
                  {resourcesData?.map((item, index) => (
                    <Button
                      key={index}
                      onClick={() => handleBtnClick(item.id, item.title)}
                      variant="contained"
                      fullWidth
                      sx={{
                        boxShadow: "none",
                        bgcolor:
                          activeButtonId === item.id ? "#602DE1" : "#F8F8F9",
                        color:
                          activeButtonId === item.id ? "#ffffff" : "#667085",
                        display: "flex",
                        justifyContent: "start",
                        alignItems: "center",
                        wordBreak: "break-word",
                        whiteSpace: "normal",
                        fontSize: "16px",
                        "&:hover": {
                          color: "#ffff",
                        },
                        textAlign: "left",
                        lineHeight: "30px",
                      }}
                      style={{
                        opacity: visibleButtons.includes(index) ? 1 : 0,
                        transform: visibleButtons.includes(index)
                          ? "translateY(0)"
                          : "translateY(20px)",
                        transition: "opacity 1s ease, transform 1s ease",
                      }}
                    >
                      {/* {isTextTruncated ? (
                          <Tooltip title={item.title} arrow>
                            <span>{`${item.title.slice(0, 25)}...`}</span>
                          </Tooltip>
                        ) : (
                          <span>{item.title}</span>
                        )} */}
                      {item.title}
                    </Button>
                  ))}
                </Box>
              </Grid>
              <Grid item container md={9} spacing={6}>
                {filteredResourcesDetails.map((item, index) => (
                  <Grid item xs={12} md={4} key={index}>
                    <Box
                      sx={{
                        opacity: visibleCards.includes(index) ? 1 : 0,
                        transform: visibleCards.includes(index)
                          ? "translateX(0)"
                          : "translateX(-20px)",
                        transition: "opacity 1s ease, transform 1s ease",
                        height: "100%",
                      }}
                    >
                      <HelpDocumentCards resourceDetail={item} />
                    </Box>
                  </Grid>
                ))}
              </Grid>
            </Grid>
          </Grid>
        </Container>
      </Box>
    </>
  );
};

export default HelpDocuments;
